import pandas as pd, numpy as np, statsmodels.api as sm
from scipy.stats import pearsonr
x=pd.read_csv('data/explore.csv');
for v in x.columns[2:-1]:
 m=sm.OLS(x.tensile_mpa,sm.add_constant(pd.concat([x[[v]],pd.get_dummies(x.lab,drop_first=True)],axis=1,dtype=float))).fit()
 print(v, round(m.params[v],4), round(m.pvalues[v],6), round(x[v].std(),3))

